  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --navy: #0A0A23;
      --gold: #FEAC32;
      --blue: #002EAD;
      --white: #FFFFFF;
      --gray-50: #F8FAFC;
      --gray-100: #F1F5F9;
      --gray-200: #E2E8F0;
      --gray-400: #94A3B8;
      --gray-600: #475569;
      --gray-800: #1E293B;
      --gray-900: #0F172A;
    }

    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      background: var(--gray-50);
      color: var(--gray-800);
      line-height: 1.6;
    }

    a { color: var(--blue); text-decoration: none; }
    a:hover { text-decoration: underline; }

    /* Header */
    .header {
      background: var(--navy);
      color: var(--white);
      padding: 1rem 1.5rem;
      position: sticky;
      top: 0;
      z-index: 100;
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      gap: 1.5rem;
    }

    .logo {
      color: var(--white);
      font-weight: 700;
      font-size: 1.25rem;
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .logo:hover { text-decoration: none; }

    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--gold);
      border-radius: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 0.875rem;
      color: var(--navy);
    }

    .search-bar {
      flex: 1;
      max-width: 400px;
      position: relative;
    }

    .search-bar input {
      width: 100%;
      padding: 0.5rem 1rem 0.5rem 2.5rem;
      border-radius: 6px;
      border: 1px solid rgba(255,255,255,0.2);
      background: rgba(255,255,255,0.1);
      color: var(--white);
      font-size: 0.875rem;
    }

    .search-bar input::placeholder { color: rgba(255,255,255,0.5); }

    .search-bar svg {
      position: absolute;
      left: 0.75rem;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: rgba(255,255,255,0.5);
    }

    .nav-desktop {
      display: flex;
      gap: 1.5rem;
    }

    .nav-desktop a {
      color: rgba(255,255,255,0.8);
      font-size: 0.875rem;
      font-weight: 500;
      transition: color 0.15s;
    }

    .nav-desktop a:hover { color: var(--white); text-decoration: none; }

    .hamburger {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 0.5rem;
    }

    .hamburger svg { width: 24px; height: 24px; color: var(--white); }

    .mobile-nav {
      display: none;
      position: absolute;
      top: 100%;
      left: 0;
      right: 0;
      background: var(--navy);
      padding: 1rem 1.5rem;
      flex-direction: column;
      gap: 1rem;
      border-top: 1px solid rgba(255,255,255,0.1);
    }

    .mobile-nav.open { display: flex; }

    .mobile-nav a {
      color: var(--white);
      font-weight: 500;
      padding: 0.5rem 0;
    }

    /* Main */
    .main {
      max-width: 800px;
      margin: 0 auto;
      padding: 2rem 1.5rem;
    }

    /* Hero */
    .donation-hero {
      text-align: center;
      margin-bottom: 2.5rem;
    }

    .donation-hero h1 {
      font-size: 2.25rem;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 1rem;
    }

    .donation-hero p {
      font-size: 1.1rem;
      color: var(--gray-600);
      max-width: 600px;
      margin: 0 auto;
      line-height: 1.7;
    }

    /* Donation Form */
    .donation-form {
      background: var(--white);
      border-radius: 16px;
      padding: 2rem;
      box-shadow: 0 4px 20px rgba(0,0,0,0.08);
      margin-bottom: 2rem;
    }

    .amount-tabs {
      display: flex;
      gap: 0.75rem;
      margin-bottom: 1.5rem;
      flex-wrap: wrap;
    }

    .amount-tab {
      flex: 1;
      min-width: 80px;
      padding: 1rem;
      border: 2px solid var(--gray-200);
      border-radius: 10px;
      background: var(--white);
      cursor: pointer;
      text-align: center;
      transition: all 0.2s;
      font-size: 1.1rem;
      font-weight: 700;
      color: var(--gray-800);
    }

    .amount-tab:hover {
      border-color: var(--gold);
      background: #FFFBEB;
    }

    .amount-tab.active {
      border-color: var(--gold);
      background: var(--gold);
      color: var(--navy);
    }

    .donation-description {
      background: var(--gray-50);
      border-radius: 10px;
      padding: 1.25rem;
      margin-bottom: 1.25rem;
      text-align: center;
      font-size: 1rem;
      color: var(--gray-700);
      min-height: 60px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .donate-btn {
      width: 100%;
      padding: 1rem;
      background: var(--gold);
      color: var(--navy);
      border: none;
      border-radius: 10px;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      transition: background 0.2s, transform 0.15s;
    }

    .donate-btn:hover {
      background: #e6a029;
      transform: scale(1.01);
    }

    .donate-btn:active { transform: scale(0.99); }

    .donation-sublabel {
      text-align: center;
      margin-top: 0.75rem;
      font-size: 0.8rem;
      color: var(--gray-400);
    }

    .donation-sublabel a {
      color: var(--blue);
      text-decoration: underline;
    }

    /* Benefits */
    .supporter-benefits {
      background: var(--white);
      border-radius: 16px;
      padding: 2rem;
      box-shadow: 0 4px 20px rgba(0,0,0,0.08);
      margin-bottom: 2rem;
    }

    .supporter-benefits h2 {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 1.25rem;
    }

    .benefits-list {
      list-style: none;
    }

    .benefits-list li {
      padding: 0.6rem 0;
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      font-size: 0.95rem;
      color: var(--gray-700);
    }

    .benefits-list svg {
      width: 20px;
      height: 20px;
      color: #10B981;
      flex-shrink: 0;
      margin-top: 2px;
    }

    /* Initiatives */
    .current-initiatives {
      background: var(--white);
      border-radius: 16px;
      padding: 2rem;
      box-shadow: 0 4px 20px rgba(0,0,0,0.08);
      margin-bottom: 2rem;
    }

    .current-initiatives h2 {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 1.25rem;
    }

    .initiatives-list {
      list-style: none;
    }

    .initiatives-list li {
      padding: 0.6rem 0;
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      font-size: 0.95rem;
      color: var(--gray-700);
    }

    .initiatives-list svg {
      width: 20px;
      height: 20px;
      color: var(--blue);
      flex-shrink: 0;
      margin-top: 2px;
    }

    /* Achievements */
    .community-achievements {
      background: linear-gradient(135deg, var(--navy) 0%, #1a1a4a 100%);
      border-radius: 16px;
      padding: 2rem;
      margin-bottom: 2rem;
    }

    .community-achievements h2 {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 1.25rem;
    }

    .achievements-list {
      list-style: none;
    }

    .achievements-list li {
      padding: 0.5rem 0;
      font-size: 0.95rem;
      color: rgba(255,255,255,0.85);
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .achievements-list li::before {
      content: '';
      width: 6px;
      height: 6px;
      background: var(--gold);
      border-radius: 50%;
      flex-shrink: 0;
    }

    .achievements-list strong {
      color: var(--gold);
      font-weight: 600;
    }

    /* FAQ */
    .faq-accordion {
      background: var(--white);
      border-radius: 16px;
      padding: 2rem;
      box-shadow: 0 4px 20px rgba(0,0,0,0.08);
      margin-bottom: 2rem;
    }

    .faq-accordion h2 {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 1.25rem;
    }

    .faq-item {
      border-bottom: 1px solid var(--gray-100);
    }

    .faq-item:last-child { border-bottom: none; }

    .faq-question {
      width: 100%;
      padding: 1rem 0;
      background: none;
      border: none;
      text-align: left;
      font-size: 0.95rem;
      font-weight: 600;
      color: var(--gray-800);
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      transition: color 0.15s;
    }

    .faq-question:hover { color: var(--navy); }

    .faq-question svg {
      width: 20px;
      height: 20px;
      color: var(--gray-400);
      transition: transform 0.3s;
      flex-shrink: 0;
    }

    .faq-item.open .faq-question svg { transform: rotate(180deg); }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.3s ease-out, padding 0.3s ease;
    }

    .faq-item.open .faq-answer {
      max-height: 500px;
      padding-bottom: 1rem;
    }

    .faq-answer p {
      font-size: 0.9rem;
      color: var(--gray-600);
      line-height: 1.7;
    }

    /* Footer */
    .footer {
      background: var(--navy);
      color: var(--white);
      padding: 3rem 1.5rem;
      margin-top: 3rem;
    }

    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-mission {
      font-size: 0.875rem;
      color: rgba(255,255,255,0.7);
      line-height: 1.7;
      margin-bottom: 2rem;
      max-width: 700px;
    }

    .footer-section-title {
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      color: var(--gold);
      margin-bottom: 1rem;
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem 1.5rem;
      margin-bottom: 2rem;
    }

    .footer-links a {
      color: rgba(255,255,255,0.7);
      font-size: 0.875rem;
      transition: color 0.15s;
    }

    .footer-links a:hover { color: var(--white); text-decoration: none; }

    .footer-bottom-links {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem 1.5rem;
      padding-top: 1.5rem;
      border-top: 1px solid rgba(255,255,255,0.1);
    }

    .footer-bottom-links a {
      color: rgba(255,255,255,0.5);
      font-size: 0.8rem;
    }

    /* Responsive */
    @media (max-width: 768px) {
      .nav-desktop { display: none; }
      .hamburger { display: block; }
      .donation-hero h1 { font-size: 1.75rem; }
      .amount-tabs { gap: 0.5rem; }
      .amount-tab { min-width: 70px; padding: 0.75rem; }
    }
  </style>
</head>
<body>
  <header class="header">
    <div class="header-inner">
      <a href="index.html" class="logo">
        <span class="logo-icon">A</span>
        OpenLearnHub
      </a>
      <div class="search-bar">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        <input type="text" placeholder="Search 12,000+ tutorials, articles, and books">
      </div>
      <nav class="nav-desktop">
        <a href="#">Forum</a>
        <a href="learn.html">Curriculum</a>
        <a href="donate.html">Donate</a>
      </nav>
      <button class="hamburger" onclick="toggleMobileNav()" aria-label="Toggle navigation">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 6h16M4 12h16M4 18h16" /></svg>
      </button>
    </div>
    <nav class="mobile-nav" id="mobileNav">
      <a href="#">Forum</a>
      <a href="learn.html">Curriculum</a>
      <a href="donate.html">Donate</a>
    </nav>
  </header>

  <main class="main">
    <div class="donation-hero">
      <h1>Help Our Charity Do More</h1>
      <p>OpenLearnHub is a highly efficient education charity. When you donate, you help people learn new skills and provide for their families. You also help us create new resources for you to use to expand your own technology skills.</p>
    </div>

    <div class="donation-form">
      <div class="amount-tabs">
        <button class="amount-tab" data-amount="5" onclick="selectAmount(5)">$5</button>
        <button class="amount-tab" data-amount="10" onclick="selectAmount(10)">$10</button>
        <button class="amount-tab active" data-amount="20" onclick="selectAmount(20)">$20</button>
        <button class="amount-tab" data-amount="40" onclick="selectAmount(40)">$40</button>
      </div>
      <div class="donation-description" id="donationDescription">
        Your $20 donation will provide <strong>1,000 hours of learning</strong> to people around the world each month.
      </div>
      <button class="donate-btn">Donate</button>
      <p class="donation-sublabel">Donating <span id="currentAmount">$20</span> / month: <a href="#">edit amount</a> · Secure donation</p>
    </div>

    <div class="supporter-benefits">
      <h2>Supporter Benefits</h2>
      <ul class="benefits-list">
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7" /></svg>
          No more donation prompt popups
        </li>
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7" /></svg>
          You'll get a Supporter badge
        </li>
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7" /></svg>
          Your profile image will get a golden halo around it
        </li>
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7" /></svg>
          You'll gain access to special Supporter Discord channels — join our Discord and use the /supporter command
        </li>
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7" /></svg>
          And more benefits to come soon
        </li>
      </ul>
    </div>

    <div class="current-initiatives">
      <h2>Current Initiatives</h2>
      <ul class="initiatives-list">
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          Creating new JavaScript and Python curricula
        </li>
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          Creating English and math curricula
        </li>
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          Translating our curriculum and tutorials into 32 languages
        </li>
        <li>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          Creating a free accredited computer science bachelor's degree
        </li>
      </ul>
    </div>

    <div class="community-achievements">
      <h2>Community Achievements</h2>
      <ul class="achievements-list">
        <li>Published <strong>193 full-length courses</strong> on YouTube</li>
        <li>Published <strong>850 text-based coding tutorials</strong> and 5 free books through OpenLearnHub Press</li>
        <li>Merged <strong>2,455 code contributions</strong> into our open source repositories on GitHub</li>
        <li>Translated <strong>1.5 million words</strong> to make our curriculum and tutorials more accessible to speakers of many world languages</li>
      </ul>
    </div>

    <div class="faq-accordion">
      <h2>Frequently Asked Questions</h2>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          How can I get help with my donations?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>Please contact our support team at support@openlearnhub.org for assistance with your donations. We typically respond within 1-2 business days.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          How transparent is OpenLearnHub?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>We publish annual reports and financial statements. Visit our "Our Charity" page for detailed information about how we operate and allocate resources.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          How efficient is OpenLearnHub?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>Over 80% of our revenue goes directly to educational programs and resources. We maintain low administrative costs to maximize impact.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          How can I make a one-time donation?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>You can make a one-time donation by selecting any amount above and clicking "Donate" without the monthly recurrence option.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          Does OpenLearnHub accept donations in Bitcoin or other cryptocurrencies?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>Currently, we accept USD through our secure payment processor. Cryptocurrency donations may be accepted in the future.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          Can I mail a physical check?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>Yes, please mail checks to: OpenLearnHub, 123 Education Lane, San Francisco, CA 94102. Include your email for a tax receipt.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          How can I set up matching gifts from my employer, or payroll deductions?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>Many employers offer matching gift programs. Contact your HR department to initiate a matching gift to OpenLearnHub using our EIN: 12-3456789.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          How can I set up an Endowment Gift to OpenLearnHub?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>Please contact our development team at giving@openlearnhub.org to discuss endowment gift options and legacy planning.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          How can I set up a Legacy gift to OpenLearnHub?
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        <div class="faq-answer"><p>Legacy gifts can be arranged through our planned giving program. Contact legacy@openlearnhub.org for more information.</p></div>
      </div>

      <div class="faq-item">
        <button class="faq-question" onclick="toggleFaq(this)">
          How can I donate stock to OpenLearnHub?
